def _configuration_prefix() -> str:
    """按优先级整组选用配置, 不跨组补齐凭据."""
    # 任一字段非空就选中该组, 随后由 require_env 检查完整性.
    # 配了一半时直接报错, 避免地址属于一组、密钥却借用另一组.
    for prefix in ("OPENROUTER", "DS_MICU"):
        if any(os.getenv(f"{prefix}_{field}", "").strip() for field in ("MODEL", "BASE_URL", "API_KEY")):
            return prefix
    return "MICU"


def _openrouter_body() -> dict[str, object]:
    """传递显式推理及选路设置, 未配置时沿用提供方默认值."""
    # 这里保留服务端默认推理行为, 只有用户显式设置才发送覆盖值.
    provider: dict[str, object] = {"require_parameters": True}
    sorting = os.getenv("OPENROUTER_PROVIDER_SORT", "").strip()
    if sorting:
        if sorting not in {"price", "throughput", "latency"}:
            msg = "Invalid OPENROUTER_PROVIDER_SORT"
            raise ValueError(msg)
        provider["sort"] = sorting
    body: dict[str, object] = {"provider": provider}
    effort = os.getenv("OPENROUTER_REASONING_EFFORT", "").strip()
    if effort:
        if effort not in {"max", "xhigh", "high", "medium", "low", "minimal", "none"}:
            msg = "Invalid OPENROUTER_REASONING_EFFORT"
            raise ValueError(msg)
        body["reasoning"] = {"effort": effort}
    return body

def create(self, report: DraftModel) -> dict[str, JsonValue]:
    """首次保存字段合法的完整草稿, 已有文件保持不变.

    Args:
        report: 草稿, 可以包含跨条目业务错误.

    Returns:
        创建状态、版本、路径与业务诊断.
    """
    with self.lock:
        self._safe_paths()
        if self.revision is not None:
            current = self.report()
            return {"created": False, "path": self.virtual_path, "revision": self.revision, "validation": self.validation(current)}
        if self.path.exists():
            msg = "已有草稿不属于当前运行实例"
            self._reject("external_draft_change", msg)
        current = self.model_type.model_validate(report.model_dump(mode="json", exclude_none=True))
        content = json.dumps(current.model_dump(mode="json", exclude_none=True), ensure_ascii=False, indent=2).encode("utf-8")
        self.directory.mkdir(parents=True, exist_ok=True)
        _atomic_write(self.path, content)
        self.revision = _digest(content)
        return {"created": True, "saved": True, "path": self.virtual_path, "revision": self.revision, "validation": self.validation(current)}

def _snapshot(self, content: bytes, revision: str) -> None:
    self.history.mkdir(exist_ok=True)
    target = self.history / f"{revision}.json"
    if target.is_symlink():
        msg = "历史快照不可为符号链接"
        self._reject("invalid_path", msg)
    if target.exists():
        if target.read_bytes() != content:
            msg = "历史快照内容与版本不一致"
            self._reject("history_conflict", msg)
    else:
        _atomic_write(target, content)

def _payload(source: CapturedPlanningSource, report: ScenePlanningSubmission) -> dict[str, bytes]:
    observations = {name: package_asset(source.observation_dir, name).read_bytes() for name in OBSERVATION_FILES}
    if content_sha256({name: observations[name] for name in OBSERVATION_CONTENT_FILES}) != source.observation_sha256:
        msg = "固定观察文件已在规划运行期间改变"
        raise ValueError(msg)
    payload = {f"observation/{name}": content for name, content in observations.items()}
    payload["request.txt"] = source.request.encode("utf-8")
    payload["generation_constraints.json"] = _json_bytes(source.constraints.model_dump(mode="json"))
    values = report.model_dump(mode="json", exclude_none=True)
    for name in ("mechanisms", "sketches", "extra_candidates"):
        payload[f"{name}.json"] = _json_bytes(values[name])
    payload["candidates.json"] = _json_bytes([row.model_dump(mode="json", exclude_none=True) for row in build_candidate_index(report)])
    payload["README.md"] = _summary(source, report).encode("utf-8")
    return payload


def _manifest(source: CapturedPlanningSource, report: ScenePlanningSubmission, contents: dict[str, bytes]) -> PlanningManifest:
    statuses = _sketch_status(source, report)
    return PlanningManifest(
        content_sha256=content_sha256(contents),
        observation_sha256=source.observation_sha256,
        files={name: hashlib.sha256(content).hexdigest() for name, content in contents.items()},
        status="completed" if "completed" in statuses.values() else "partial",
        sketch_status=statuses,

def _delivery(directory: Path, reference: bytes, result: SceneAnalysisResult) -> None:
    """只发布已接受的观察快照; 失败由调用方统一转为公开终态."""
    if result.observations is None or result.submission is None or result.status == "failed":
        return
    manifest = ObservationManifest(
        reference=ObservationReference(sha256=hashlib.sha256(reference).hexdigest()),
        status="partial" if result.submission.gaps else "completed",
        context_notes=result.submission.context_notes,
        open_questions=result.submission.open_questions,
        gaps=result.submission.gaps,
    )
    write_observation_package(directory / "report", result.observations, manifest, reference)
    log_analysis(
        directory, "报告包已发布", details={"status": manifest.status, "report_dir": str(directory / "report"), "analysis_protocol": PROTOCOL}
    )


def _published_result(directory: Path, reference: bytes, result: SceneAnalysisResult) -> SceneAnalysisResult:
    try:
        _delivery(directory, reference, result)
    except Exception as error:  # noqa: BLE001  # 发布异常必须留下 failed 索引, 接受快照仍由会话保存.
        reason = f"publish_error: {type(error).__name__}: {error}"
        return replace(result, status="failed", error=reason if result.error is None else result.error + "; " + reason)

def begin_model_call(self) -> bool:
    """终态先于计数; 用尽预算后结束而不请求模型."""
    with self._lock:
        if self.state != "running":
            return False
        if self.model_calls >= self.options.max_model_calls:
            self.state, self.reason = "stopped", "model_call_limit"
            return False
        self.model_calls += 1
        return True

def bind_request(self) -> None:
    """绑定产生下一工具响应的草稿版本."""
    self.request_revision = self.draft.revision

def save_draft(self, report: SceneObservationSubmission) -> dict[str, JsonValue]:
    """首次保存结构合法草稿, 业务引用问题作为诊断返回."""
    with self._lock:
        self._require_running()
        return self.draft.create(report)

def edit_draft(self, old: str, new: str, *, replace_all: bool = False) -> dict[str, JsonValue]:
    """按本次响应绑定版本修改唯一草稿片段."""
    with self._lock:
        self._require_running()
        self.last_edit = self.draft.edit(old, new, expected_revision=self.request_revision, replace_all=replace_all)
        if self.last_edit.get("before_revision") != self.last_edit.get("revision"):
            self._reads.invalidate()
        return self.last_edit

def record_draft_read(self, identity: str, content: str) -> None:
    """只登记实际工具正文完整包含的同版本行范围."""
    with self._lock:
        self._reads.record(identity, content)

def present_reads(self, messages: list[object]) -> None:
    """成功主请求中确实包含回读结果后更新已见版本."""
    with self._lock:
        self._reads.present(messages)

def _unseen_message(self, text: str, revision: str) -> str:
    return self._reads.unseen_message(text, revision)

def finish_draft(self) -> dict[str, JsonValue]:
    """核查最新全文已进入主请求后冻结并接受同一版本."""
    with self._lock:
        self._require_running()
        text, revision = self.draft.read(expected_revision=self.request_revision)
        if self.seen_revision != revision:
            msg = self._unseen_message(text, revision)
            code = "draft_unseen"
            raise DraftError(code, msg)
        try:
            result = self._submit(self.draft.report(expected_revision=revision))
        except ValueError as error:
            code = "invalid_observations"
            raise DraftError(code, str(error)) from error
        return {**result, "accepted_revision": revision}

def _reserve(self) -> None:
    with self._lock:
        if self.state != "running" or self._saving:
            msg = "当前会话不能接受新的观察提交"
            raise ValueError(msg)
        self._saving = True

def _submit(self, report: SceneObservationSubmission) -> dict[str, JsonValue]:
    """验证完整观察并在快照成功写入后接受, 保留原短 ID."""
    frozen = report.model_copy(deep=True)
    observations = build_scene_observations(frozen)
    self._reserve()
    try:
        write_snapshot(
            self.directory / "results" / "observations.json",
            {"submission": frozen.model_dump(mode="json"), "observations": observations.model_dump(mode="json")},
        )
        self._accept(frozen, observations)
    except OSError:
        with self._lock:
            self.state, self.reason = "stopped", "snapshot_error"
        raise
    finally:
        with self._lock:
            self._saving = False
    self.save_manifest()
    return {"accepted": True, "snapshot": "results/observations.json"}

def _accept(self, report: SceneObservationSubmission, observations: SceneObservations) -> None:
    with self._lock:
        if self.state != "running":
            msg = "写入快照期间会话已结束, 候选不登记为接受结果"
            raise ValueError(msg)
        self.submission, self.observations, self.state = report, observations, "accepted"

def _planning_state(inputs: CapturedPlanningInputs) -> BlackboardState:
    target = TargetRecord(version="T1", request=inputs.request, reference_path=inputs.reference_path, constraints=("单 Pass GLSL ES 3.00 mainImage",))
    task = TaskRecord(
        id="G1",
        role="generation",
        target_version=target.version,
        objective=f"按固定整图方案 {inputs.binding.sketch_id} 实现完整 E/F/R",
        generation_binding=inputs.binding,
        allowed_changes=("实现生效 choices 与 composition, 保持跨元素关系", "依据原图调节方案内数值, 保留已知必要缺口"),
        stop_conditions=("选择已渲染并实际回读预览的候选, 如实记录差异及两类缺口",),
    )
    return add_task(add_target(new_blackboard(), target), task)


def _prepare_planning_generation(
    planning_dir: Path, sketch_id: str, *, alternative_index: int | None = None, options: GenerationOptions | None = None
) -> PreparedPlanningGeneration:
    directory = create_run_directory(options.output_dir if options is not None else None)
    try:
        inputs = capture_planning_generation_inputs(planning_dir, directory, sketch_id, alternative_index=alternative_index, options=options)
        state = _planning_state(inputs)
        save_run(directory, state, {"task_id": "G1", "phase": "prepared", "inputs": {"planning": inputs.metadata()}})
        return PreparedPlanningGeneration(run_dir=directory, state=state, inputs=inputs)

def _publish(session: PlanningSession, result: ScenePlanningResult) -> tuple[ScenePlanningResult, Path | None]:
    if result.submission is None:
        return result, None
    try:
        directory = write_planning_package(session.directory / "report", session.source, result.submission)
    except Exception as error:  # noqa: BLE001  # 正式发布失败仍交付已接受快照和 failed 索引.
        reason = f"publish_error: {type(error).__name__}: {error}"
        return replace(result, status="failed", error=f"{result.error}; {reason}" if result.error else reason), None
    return result, directory

def finish_draft(self) -> dict[str, JsonValue]:
    """校验最新已见版本并冻结接受, 不接收再次提交的正文."""
    with self._lock:
        self._require_running()
        text, revision = self.draft.read(expected_revision=self.request_revision)
        if self.seen_revision != revision:
            msg = self._reads.unseen_message(text, revision)
            code = "draft_unseen"
            raise DraftError(code, msg, path=DRAFT_PATH)
        report = self.draft.report(expected_revision=revision)
        try:
            validate_scene_planning(report, self.source.observations)
        except ValueError as error:
            code = "invalid_planning"
            raise DraftError(code, str(error), path=DRAFT_PATH) from error
        self._accept(report, revision)
        return {"accepted": True, "snapshot": "results/planning.json", "accepted_revision": revision}

def _accept(self, report: ScenePlanningSubmission, revision: str) -> None:
    frozen = ScenePlanningSubmission.model_validate(report.model_dump(mode="json", exclude_none=True))
    try:
        write_snapshot(
            self.directory / "results/planning.json",
            {"submission": frozen.model_dump(mode="json"), "observation_sha256": self.source.observation_sha256},
        )
    except OSError:
        self.state, self.reason = "stopped", "snapshot_error"
        raise
    self.submission, self.accepted_revision, self.state = frozen, revision, "accepted"
    self.save_manifest()

def stop(self, reason: str) -> dict[str, JsonValue]:
    """保存明确受阻原因, 草稿留在本轮目录."""
    if not reason.strip():
        msg = "停止原因不能为空"
        raise ValueError(msg)
    with self._lock:
        self._require_running()
        self.state, self.reason = "stopped", reason
        self.save_manifest()
        return {"stopped": True, "reason": reason}

def finalize(self, error: str | None = None) -> ScenePlanningResult:
    """根据接受事实和两类必要缺口生成最终核查结果."""
    with self._lock:
        if self.state == "running":
            self.state, self.reason = "stopped", error or "Agent 结束时未完成合法规划"
        complete = (
            self.submission is not None and not self.source.observation_manifest.gaps and any(not item.gaps for item in self.submission.sketches)
        )
        status = "failed" if self.submission is None else "completed" if complete else "partial"
        return ScenePlanningResult(status=status, submission=self.submission, error=error or self.reason, execution=self.execution())
